+++ b/test/migration.test.ts	2026-10-29 19:30:29.147703826 +0000
@@ -0,0 +1,122 @@
+import { beforeEach, describe, expect, test } from 'bun:test';
+import { db, reset } from '../src/db.ts';
+import { HttpError } from '../src/errors.ts';
+import { createUser } from '../src/handlers/users/createUser.ts';
+import { getUser } from '../src/handlers/users/getUser.ts';
+import { renameUser } from '../src/handlers/users/renameUser.ts';
+import { deactivateUser } from '../src/handlers/users/deactivateUser.ts';
+import { createOrder } from '../src/handlers/orders/createOrder.ts';
+import { adjustStock } from '../src/handlers/stock/adjustStock.ts';
+import { transferStock } from '../src/handlers/stock/transferStock.ts';
+
+const fails = async (p: Promise<unknown>, status: number, message: string) => {
+  const e = await p.then(() => undefined, (err) => err);
+  expect(e).toBeInstanceOf(HttpError);
+  expect(e).toMatchObject({ status, message });
+};
+
+beforeEach(() =>
+  reset({
+    users: [{ id: 'u1', name: 'Ann', active: true }, { id: 'u2', name: 'Bo', active: true }, { id: 'u3', name: 'Cy', active: false }],
+    stock: [{ id: 'MUG', units: 10 }, { id: 'TEE', units: 2 }],
+    orders: [
+      { id: 'o1', user: 'u1', sku: 'MUG', quantity: 1, status: 'open' },
+      { id: 'o2', user: 'u1', sku: 'TEE', quantity: 1, status: 'shipped' },
+      { id: 'o3', user: 'u1', sku: 'MUG', quantity: 2, status: 'open' },
+    ],
+  }),
+);
+
+describe('checks run in the same order as before', () => {
+  test('renameUser checks the user before the name', async () => {
+    await fails(renameUser({ id: 'zz', name: '' }), 404, 'no user zz');
+  });
+  test('createUser checks the name before the db', async () => {
+    await fails(createUser({ id: 'u1', name: ' ' }), 400, 'name is required');
+  });
+  test('createOrder checks quantity before the user', async () => {
+    await fails(createOrder({ id: 'o9', user: 'zz', sku: 'MUG', quantity: 0 }), 400, 'quantity must be a positive integer');
+  });
+  test('transferStock checks same sku before stock', async () => {
+    await fails(transferStock({ from: 'TEE', to: 'TEE', units: 99 }), 400, 'from and to are the same');
+  });
+});
+
+describe('writes', () => {
+  test('an unchanged rename writes nothing', async () => {
+    const put = db.promises.put;
+    let calls = 0;
+    db.promises.put = async (...args) => {
+      calls++;
+      return put(...args);
+    };
+    try {
+      expect(await renameUser({ id: 'u2', name: 'Bo' })).toMatchObject({ name: 'Bo' });
+    } finally {
+      db.promises.put = put;
+    }
+    expect(calls).toBe(0);
+  });
+  test('a failed check writes nothing', async () => {
+    await fails(createOrder({ id: 'o10', user: 'u2', sku: 'TEE', quantity: 3 }), 409, 'only 2 TEE left');
+    expect(await db.promises.get('stock', 'TEE')).toMatchObject({ units: 2 });
+    await fails(adjustStock({ sku: 'TEE', delta: -9 }), 409, 'stock of TEE would be -7');
+    expect(await db.promises.get('stock', 'TEE')).toMatchObject({ units: 2 });
+  });
+  test('transferStock writes the source first', async () => {
+    const put = db.promises.put;
+    const ids: string[] = [];
+    db.promises.put = async (t, row) => {
+      ids.push(row.id);
+      return put(t, row);
+    };
+    try {
+      await transferStock({ from: 'MUG', to: 'TEE', units: 1 });
+    } finally {
+      db.promises.put = put;
+    }
+    expect(ids).toEqual(['MUG', 'TEE']);
+  });
+  test('deactivateUser cancels one order at a time', async () => {
+    const put = db.promises.put;
+    let inFlight = 0;
+    let max = 0;
+    db.promises.put = async (t, row) => {
+      inFlight++;
+      max = Math.max(max, inFlight);
+      try {
+        return await put(t, row);
+      } finally {
+        inFlight--;
+      }
+    };
+    try {
+      expect(await deactivateUser({ id: 'u1' })).toEqual({ cancelled: 2 });
+    } finally {
+      db.promises.put = put;
+    }
+    expect(max).toBe(1);
+  });
+});
+
+describe('errors and return values', () => {
+  test('a db error passes through unchanged', async () => {
+    const get = db.promises.get;
+    const boom = new Error('boom');
+    db.promises.get = async () => {
+      throw boom;
+    };
+    try {
+      const e = await getUser({ id: 'u1' }).then(() => undefined, (err) => err);
+      expect(e).toBe(boom);
+      expect(e).not.toBeInstanceOf(HttpError);
+    } finally {
+      db.promises.get = get;
+    }
+  });
+  test('handlers return a Promise even on bad input', async () => {
+    const p = createUser({ id: 'x', name: '' });
+    expect(p).toBeInstanceOf(Promise);
+    await fails(p, 400, 'name is required');
+  });
+});

