diff -ruN '--exclude=node_modules' '--exclude=.git' a/test/loop-review.test.ts b/test/loop-review.test.ts
--- a/test/loop-review.test.ts	1970-01-01 00:00:00.000000000 +0000
+++ b/test/loop-review.test.ts	2026-10-29 19:44:10.561813017 +0000
@@ -0,0 +1,62 @@
+import { describe, expect, test } from 'bun:test';
+import { mkdtempSync } from 'node:fs';
+import { tmpdir } from 'node:os';
+import { join } from 'node:path';
+import { buildMessages } from '../src/core/context/build.ts';
+import { runPrompt, type RunOptions } from '../src/core/loop/run.ts';
+import { FAUX_MODEL } from '../src/core/providers/catalog.ts';
+import { fauxProvider, text, toolUse, type FauxStep } from '../src/core/providers/faux.ts';
+import { SessionLog } from '../src/core/session/log.ts';
+import { bashTool } from '../src/core/tools/bash.ts';
+import { readTool } from '../src/core/tools/read.ts';
+import type { EventOf, SessionEvent } from '../src/core/types.ts';
+
+const cwd = mkdtempSync(join(tmpdir(), 'cedia-loop-review-'));
+
+function setup(steps: FauxStep[], extra: Partial<RunOptions> = {}) {
+  const log = SessionLog.create();
+  const sleeps: number[] = [];
+  const opts: RunOptions = {
+    log,
+    provider: fauxProvider(steps),
+    model: FAUX_MODEL,
+    tools: [readTool, bashTool],
+    system: 'sys',
+    cwd,
+    retry: { sleep: async (ms) => void sleeps.push(ms) },
+    ...extra,
+  };
+  return { log, opts, sleeps };
+}
+
+const of = <K extends SessionEvent['kind']>(events: SessionEvent[], k: K) => events.filter((e): e is EventOf<K> => e.kind === k);
+const quota = (retryAfterMs: number): FauxStep => ({ error: { code: 'quota', status: 429, message: 'usage limit reached', retryAfterMs } });
+
+describe('quota waits and retries', () => {
+  // Retry-after 0 names no time: waiting "0 ms" again and again would never reach the ceiling.
+  test('a quota error with retry-after 0 is not waited out', async () => {
+    const zero = Array.from({ length: 10 }, () => quota(0));
+    const { log, opts, sleeps } = setup([...zero, { blocks: [text('ok')] }], { quotaWaitMs: 60_000 });
+    expect((await runPrompt(opts, 'hi')).subtype).toBe('error_during_execution');
+    expect(sleeps).toEqual([]);
+    expect(of(log.events, 'attempt')).toHaveLength(1);
+  });
+
+  // A wait is not a failed attempt: after a wait, five transient errors in a row still get their retries.
+  test('a quota wait does not use up the transient retries of the run', async () => {
+    const server: FauxStep = { error: { code: 'server', status: 500, message: 'boom' } };
+    const { opts, sleeps } = setup([quota(1000), server, server, server, server, { blocks: [text('ok')] }], { quotaWaitMs: 60_000 });
+    expect(await runPrompt(opts, 'hi')).toMatchObject({ subtype: 'success' });
+    expect(sleeps).toEqual([1000, 1000, 2000, 4000, 8000]);
+  });
+});
+
+describe('replayed tool calls', () => {
+  // The log keeps both blocks of the reply; the provider gets one tool_use per id, since the call ran once.
+  test('a reply that repeats a call id is replayed with one tool_use for it', async () => {
+    const { log, opts } = setup([{ blocks: [toolUse('dup', 'bash', { command: 'echo one' }), toolUse('dup', 'bash', { command: 'echo two' })] }, { blocks: [text('ok')] }]);
+    await runPrompt(opts, 'go');
+    const replayed = buildMessages(log.events).flatMap((m) => (m.role === 'assistant' ? m.blocks : []));
+    expect(replayed.filter((b) => b.type === 'tool_use')).toHaveLength(1);
+  });
+});

